<?php
/**
 * Zinn® SEO abilities for AI agents (MCP) and the abilities REST API (zs-211, zs-212, zs-213).
 *
 * @package ZinnDigital\ZinnSEO
 */

declare( strict_types = 1 );

namespace ZinnDigital\ZinnSEO\Mcp;

use ZinnDigital\ZinnSEO\Capabilities;
use ZinnDigital\ZinnSEO\McpKit\Ability;
use ZinnDigital\ZinnSEO\McpKit\Rest_Bridge;

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

/**
 * Every REST route of the plugin is an ability of its own (class-rest-map.php, generated by
 * wp/bin/mcp-rest-map.py from its curated table; the unit suite fails on a route with no
 * answer), so an agent can do whatever a person can on the plugin's screens, checked by the
 * same permission and validated the same way. Credit checks (rank, index, AI visibility,
 * backlinks …) are among them and spend the site owner's Zinn® credits exactly as the screens
 * do (zs-213).
 *
 * Hand-written here: the "Optimise this site" prompt (zs-212), a guided run an agent's user picks.
 */
final class Abilities {

	/** The ability category (and name prefix). */
	public const CATEGORY = 'zinn-seo';

	/**
	 * Register (on `wp_abilities_api_init`).
	 *
	 * @return void
	 */
	public static function register(): void {
		// ⛔ Nothing is built where no MCP or REST request is served (a WP-CLI command other than
		// `wp mcp-adapter …`): the map's ~400 entries and the module list cost ~8 MB, and beside
		// WooCommerce they pushed `wp plugin is-active` past 128 MB (P13, measured 2026-10-13:
		// 167.5 MB with the switch on, 159.6 off). The kit would register nothing there anyway.
		if ( ! Rest_Bridge::may_resolve() ) {
			return;
		}
		// "Optimise this site" is Pro (zs-212): its module ships in the premium package only.
		if ( \ZinnDigital\ZinnSEO\Modules::enabled( 'mcp-pro' ) ) {
			self::register_prompt();
		}

		require_once __DIR__ . '/class-rest-map.php';
		Rest_Bridge::register( Rest_Map::entries(), self::CATEGORY );
	}

	/**
	 * The "Optimise this site" prompt (Pro).
	 *
	 * @return void
	 */
	private static function register_prompt(): void {
		Ability::register(
			'zinn-seo/optimise-site',
			array(
				'mcp_type'            => 'prompt',
				'edition'             => 'pro',
				'capability'          => Capabilities::MANAGE,
				'label'               => __( 'Optimise this site', 'zinn-seo' ),
				'description'         => __( 'A guided run: the agent audits the site, proposes a plan, tries every change first, applies what you agree to as undoable changes, and reports what it did.', 'zinn-seo' ),
				'category'            => self::CATEGORY,
				'input_schema'        => array(
					'type'                 => 'object',
					'properties'           => array(
						'focus' => array(
							'type'        => 'string',
							'description' => __( 'What matters most to you, e.g. "the shop pages" or "titles and descriptions". Leave empty for the whole site.', 'zinn-seo' ),
						),
					),
					'additionalProperties' => false,
				),
				'execute_callback'    => array( self::class, 'optimise_prompt' ),
				'permission_callback' => static fn(): bool => Capabilities::can_manage(),
			)
		);
	}

	/**
	 * The `zinn-seo/optimise-site` prompt (zs-212, zs-inn-18): audit → plan → apply as revisions →
	 * report, with the site owner's write mode and the dry run built in.
	 *
	 * @param array<string, mixed> $input Input.
	 * @return array<string, mixed>
	 */
	public static function optimise_prompt( array $input ): array {
		$focus = sanitize_text_field( (string) ( $input['focus'] ?? '' ) );
		$text  = __( 'Optimise this WordPress site\'s SEO with the Zinn® SEO tools. Work in four steps and keep me informed.', 'zinn-seo' ) . "\n\n"
			. __( '1) AUDIT (read only): call zinn-seo-get-info and zinn-seo-get-settings; call zinn-seo-list-findings for what the plugin already found; call zinn-seo-list-modules to see what is switched off. If credit checks are available (zinn-seo-get-credits), tell me what a site audit or rank check would cost before running one.', 'zinn-seo' ) . "\n"
			. __( '2) PLAN: list the changes you propose, most valuable first — page titles and descriptions (zinn-seo-update-fields, or zinn-seo-bulk-update-fields for many pages), structured data, redirects for missing pages (zinn-seo-list-missing-pages, zinn-seo-create-redirect), sitemaps, robots.txt and llms.txt — each with the tool and values you would use and why. Wait for my yes.', 'zinn-seo' ) . "\n"
			. __( '3) APPLY: send each change with dry_run: true first and show me the difference; then send it without dry_run. Every change is recorded in the change history as an AI agent change and can be undone there (zinn-seo-list-field-history, zinn-seo-restore-field-change, with Pro). If an answer says the change is waiting for approval, tell me and continue; if it says agents may only read, stop and give me the plan.', 'zinn-seo' ) . "\n"
			. __( '4) REPORT: list what you changed, what is waiting for approval, what you left and why, and what to check again in a week.', 'zinn-seo' );
		if ( '' !== $focus ) {
			/* translators: %s: what the site owner wants the agent to concentrate on. */
			$text .= "\n\n" . sprintf( __( 'Concentrate on: %s.', 'zinn-seo' ), $focus );
		}

		return array(
			'messages' => array(
				array(
					'role'    => 'user',
					'content' => array(
						'type' => 'text',
						'text' => $text,
					),
				),
			),
		);
	}
}
